css:
[data-bz-node="site-header"] { position: fixed; top: 0; left: 0; right: 0; z-index: 70; padding: 0; background: linear-gradient(180deg, rgba(2,6,23,.92), rgba(2,6,23,.55)); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px); border-bottom: 1px solid rgba(255,255,255,.07); }
[data-bz-node="header-row"] { align-items: center; gap: 20px; display: flex; justify-content: space-between; padding: 16px 40px; }
[data-bz-node="header-row"] > .bz-col { width: auto; flex: 0 0 auto; }
[data-bz-node="header-brand"] .bz-block--logo, [data-bz-node="header-brand"] .bz-brand { display: flex; }
[data-bz-node="header-right"] { display: flex; align-items: center; justify-content: flex-end; gap: 30px; }
[data-bz-node="header-right"] > * { margin: 0 !important; }
[data-bz-node="header-right"] .bz-btns { margin: 0; }
[data-bz-node="main-nav"] .bz-nav { gap: 30px; }
[data-bz-node="main-nav"] a { font-family: var(--font-body); color: #c4d4e2; font-size: 13px; font-weight: 500; line-height: normal; letter-spacing: .14em; text-transform: uppercase; transition: color .25s ease; }
[data-bz-node="main-nav"] a:hover, [data-bz-node="main-nav"] a[aria-current="page"], [data-bz-node="main-nav"] a[data-current] { color: #00fbff; }
.bz-menu-toggle { color: #f4fbff; border-color: rgba(255,255,255,.25); border-radius: 4px; }
/* The handoff keeps the full menu in the bar down to phone width, so the platform's 1100px collapse is lifted between 641 and 1100. */
@media (min-width: 641px) and (max-width: 1100px) {
  [data-bz-node="main-nav"] .bz-menu-toggle { display: none; }
  [data-bz-node="main-nav"] .bz-menu-wrap > .bz-menu { display: block !important; position: static; padding: 0; background: none; border: 0; }
  [data-bz-node="main-nav"] .bz-nav { flex-direction: row; align-items: center; gap: 30px; }
}
@media (max-width: 640px) {
  [data-bz-node="header-row"] { position: relative; }
  [data-bz-node="main-nav"] .bz-menu-wrap { position: static; }
  .bz-menu-wrap[data-open] > .bz-menu { left: 0; right: 0; top: 100%; background: #041c30; border-top: 1px solid rgba(255,255,255,.1); padding: 16px 20px 20px; }
  .bz-menu-wrap[data-open] .bz-nav { gap: 18px; }
}
@media (max-width: 820px) { [data-bz-node="header-right"] { gap: 14px; } [data-bz-node="header-row"] { padding: 14px 20px; } }

