// Mark the current section in the main menu: /athletes/<name> lights up "Athletes".
(function () {
  var path = location.pathname.replace(/\/$/, '') || '/';
  document.querySelectorAll('[data-bz-node="main-nav"] a').forEach(function (a) {
    var h = (a.getAttribute('href') || '').split('#')[0].replace(/\/$/, '') || '/';
    if (h.indexOf('/') !== 0 || a.getAttribute('href').indexOf('#') > -1) return;
    var program = ['/athletes/apply', '/athletes/terms', '/athletes/privacy'];
    if (program.indexOf(path) > -1) return;
    if (h === path || (h !== '/' && path.indexOf(h + '/') === 0)) a.setAttribute('data-current', '');
  });
})();
